----------------------------------------------------------------------
-- VoidAH ProfessionPlans -- the cheapest leveling path for each crafting
-- profession, worked out live when you pick one in the Professions tab.
--
-- Recipes come from Blizzard's game tables (ProfessionData.lua, generated by
-- voidscout-data/tools/cmd/prof-data): when each recipe turns yellow and grey,
-- how many points it gives, and its materials. Prices are your own:
--   1. VoidAH's Auction House scan data (the cheapest quality of a material),
--   2. vendor prices VoidAH saw at a merchant you visited,
--   3. else the game's listed buy price, marked "est." (exact for vendor goods).
-- Recipes you know come first (VoidUIAuctionDB.profCache, captured in
-- AuctionUI.lua when you open the profession window); where none of them gives
-- skill, the cheapest one you don't know yet is used and flagged NOT LEARNED.
--
-- The path: from your skill to the cap, each craft is the recipe with the
-- lowest cost per expected skill point. Orange always gives its points; past
-- yellow the chance falls off to 0 at grey ((grey - skill) / (grey - yellow)).
--
-- VoidUI.ProfessionPlans holds one entry per profession for the tab's list;
-- VoidUI.BuildProfessionPlan(entry, skill) returns the plan the tab shows:
-- { name, skill, notes, steps = { startSkill, endSkill, recipe, spellID, count,
--   per, source }, mats = { { qty, name, itemID, priceText } } }.
----------------------------------------------------------------------

VoidUI = VoidUI or {}

local DATA = VoidUI.ProfessionData or { professions = {}, items = {} }
local MAX_SKILL = 100

VoidUI.ProfessionPlans = {}
for _, p in ipairs(DATA.professions) do
    VoidUI.ProfessionPlans[#VoidUI.ProfessionPlans + 1] = { id = p.id, name = p.name, skill = p.name, data = p }
end

----------------------------------------------------------------------
-- Vendor prices: recorded at merchants for the materials recipes use.
----------------------------------------------------------------------
local function VendorPrices()
    VoidUIAuctionDB = VoidUIAuctionDB or {}
    VoidUIAuctionDB.vendorPrices = VoidUIAuctionDB.vendorPrices or {}
    return VoidUIAuctionDB.vendorPrices
end

local merchantWatch = CreateFrame("Frame")
merchantWatch:RegisterEvent("MERCHANT_SHOW")
merchantWatch:RegisterEvent("MERCHANT_UPDATE")
merchantWatch:SetScript("OnEvent", function()
    if not (C_MerchantFrame and C_MerchantFrame.GetItemInfo and GetMerchantNumItems) then return end
    local prices = VendorPrices()
    for i = 1, GetMerchantNumItems() or 0 do
        local link = GetMerchantItemLink(i)
        local id = link and tonumber(link:match("item:(%d+)"))
        if id and DATA.items[id] then
            local ok, info = pcall(C_MerchantFrame.GetItemInfo, i)
            -- gold only: a price in currency or items isn't comparable
            if ok and info and info.price and info.price > 0 and not info.hasExtendedCost then
                prices[id] = math.floor(info.price / math.max(info.stackCount or 1, 1))
            end
        end
    end
end)

----------------------------------------------------------------------
-- Prices
----------------------------------------------------------------------
-- Cheapest way to get one of a material (any quality): price, source, itemID.
local function UnitPrice(ids)
    local AH = VoidUI.AH
    local best, src, bestID
    for _, id in ipairs(ids) do
        local p = AH and AH.GetPrice and AH:GetPrice(id)
        if p and p > 0 and (not best or p < best) then best, src, bestID = p, "ah", id end
    end
    local vendor = VendorPrices()
    for _, id in ipairs(ids) do
        local v = vendor[id]
        if v and v > 0 and (not best or v < best) then best, src, bestID = v, "vendor", id end
    end
    if not best then
        local it = DATA.items[ids[1]]
        if it and (it.buy or 0) > 0 then best, src, bestID = it.buy, "est", ids[1] end
    end
    return best, src, bestID or ids[1]
end

local function ItemName(id)
    return C_Item.GetItemNameByID(id) or (DATA.items[id] and DATA.items[id][1]) or ("item " .. id)
end

local function Money(copper)
    if VoidUI.FormatMoney then return VoidUI:FormatMoney(math.floor(copper + 0.5)) end
    return string.format("%.1fg", copper / 10000)
end

----------------------------------------------------------------------
-- The plan
----------------------------------------------------------------------
function VoidUI.BuildProfessionPlan(entry, skill)
    local prof = entry and entry.data
    if not prof then return entry end
    local cache = VoidUIAuctionDB and VoidUIAuctionDB.profCache and VoidUIAuctionDB.profCache[entry.skill]
    local known = cache and cache.recipes
    -- Always the expansion's cap: a recipe sync remembers the cap of its day
    -- (a week-old one said 75 while the real cap was 100).
    local target = MAX_SKILL

    -- Every recipe with its cost per craft; known = you can craft it now.
    local recipes, unpriced = {}, 0
    for _, r in ipairs(prof.recipes) do
        local id = r[1]
        local isKnown = (known and known[id] ~= nil)
            or (C_SpellBook and C_SpellBook.IsSpellKnown and C_SpellBook.IsSpellKnown(id)) or false
        do
            local cost, est, mats = 0, false, {}
            for _, m in ipairs(r.mats) do
                local price, src, itemID = UnitPrice(m.ids)
                if not price then cost = nil; break end
                cost = cost + price * m.n
                if src == "est" then est = true end
                mats[#mats + 1] = { id = itemID, n = m.n }
            end
            if cost then
                recipes[#recipes + 1] = { id = id, name = r[2], min = r.min, yellow = r.yellow, grey = r.grey,
                    ups = r.ups, cost = cost, est = est, mats = mats, known = isKnown }
            else
                unpriced = unpriced + 1   -- said in the notes if the path stops short
            end
        end
    end

    -- Your skill in THIS expansion's line (Midnight Alchemy): from the game when
    -- it has it loaded, else what VoidAH recorded at your profession window. Never
    -- the base profession numbers: those can be another line's (the tab once
    -- showed 100/75 for a 51/100 Midnight Alchemy).
    local live
    if C_TradeSkillUI and C_TradeSkillUI.GetProfessionInfoBySkillLineID then
        local ok, info = pcall(C_TradeSkillUI.GetProfessionInfoBySkillLineID, prof.tier)
        if ok and info and (info.maxSkillLevel or 0) > 0 then
            live = { skill = info.skillLevel or 0, max = info.maxSkillLevel }
        end
    end
    live = live or (cache and cache.tiers and cache.tiers[prof.tier])
    skill = live and live.skill or 0

    -- Craft by craft: the cheapest cost per expected point at the current skill,
    -- from the recipes you know; when none of them gives skill, the cheapest one
    -- you don't know yet (flagged NOT LEARNED), so the path still reaches the cap.
    -- A character with only old-expansion recipes (seen 2026-10-30) gets the full
    -- path and learns what to pick up.
    -- Skill moves in whole points: at skill s the chance of a skill-up is fixed,
    -- so the next success takes 1/chance crafts on average and adds `ups` points.
    -- (Adding the expected gain as a fraction made the chance drop before a real
    -- point was earned, and the plan stopped short of grey.)
    local s = math.max(skill or 0, 1)
    local start = s
    local steps, cur, guard = {}, nil, 0
    while s < target and guard < 1000 do
        guard = guard + 1
        local best, bestCPP, bestChance
        -- 1: known recipes, 2: ones you don't know; a recipe you know may grind
        -- out the last points at low odds before you're sent to learn a new one
        -- for a single point. 3: anything with any chance at all, so the odds
        -- floors never end the path short of the cap.
        for pass = 1, 3 do
            if best then break end
            local floor = pass == 1 and 0.02 or pass == 2 and 0.05 or 0
            for _, r in ipairs(recipes) do
                if (pass == 3 or r.known == (pass == 1)) and r.min <= s and s < r.grey then
                    local chance = 1
                    if s >= r.yellow and r.grey > r.yellow then chance = (r.grey - s) / (r.grey - r.yellow) end
                    if chance > 0 and chance >= floor then
                        -- points past the cap are worth nothing: at 99, a +5 recipe
                        -- buys one point like a +1 does
                        local cpp = r.cost / (chance * math.min(r.ups, target - s))
                        if not bestCPP or cpp < bestCPP then best, bestCPP, bestChance = r, cpp, chance end
                    end
                end
            end
        end
        if not best then break end
        if not cur or cur.r ~= best then
            cur = { r = best, from = s, count = 0 }
            steps[#steps + 1] = cur
        end
        cur.count = cur.count + 1 / bestChance   -- expected crafts for this skill-up
        s = math.min(s + best.ups, target)
        cur.to = s
    end
    for _, st in ipairs(steps) do st.count = math.ceil(st.count - 1e-6) end
    local reached = s

    -- Shape it for the tab: steps, totals per material, notes.
    local plan = { id = entry.id, name = entry.name .. " leveling", skill = entry.skill, steps = {}, mats = {},
        skillLevel = live and live.skill, maxSkillLevel = live and live.max, skillUnknown = not live }
    local totals, order, totalCost, anyEst, toLearn = {}, {}, 0, false, 0
    for _, st in ipairs(steps) do
        local per = {}
        for _, m in ipairs(st.r.mats) do
            per[#per + 1] = m.n .. "x " .. ItemName(m.id)
            if not totals[m.id] then totals[m.id] = 0; order[#order + 1] = m.id end
            totals[m.id] = totals[m.id] + m.n * st.count
        end
        totalCost = totalCost + st.r.cost * st.count
        if st.r.est then anyEst = true end
        if not st.r.known then toLearn = toLearn + 1 end
        plan.steps[#plan.steps + 1] = {
            startSkill = st.from, endSkill = math.max(st.to or st.from, st.from), recipe = st.r.name,
            spellID = st.r.id, count = st.count, per = table.concat(per, ", "),
            source = (not st.r.known) and "a trainer, vendor or renown" or nil,
        }
    end
    table.sort(order, function(a, b) return totals[a] > totals[b] end)
    for _, id in ipairs(order) do
        local price, src = UnitPrice({ id })
        local priceText = price and (Money(price) .. (src == "est" and " est." or src == "vendor" and " vendor" or "") .. " each") or nil
        plan.mats[#plan.mats + 1] = { totals[id], ItemName(id), id, priceText }
    end

    local notes = {}
    if #steps == 0 then
        notes[#notes + 1] = (start >= target) and ("|cff66ff66You're at " .. target .. ": nothing left to level.|r")
            or "|cffff8800No recipe gives skill from here.|r"
    else
        notes[#notes + 1] = ("Cheapest path from |cffffffff%d|r to |cffffffff%d|r: about |cffffd200%s|r in materials (VoidAH prices%s)."):format(
            start, reached, Money(totalCost), anyEst and "; |cffaaaaaaest.|r = no Auction House price yet" or "")
        if reached < target then
            notes[#notes + 1] = ("|cffff8800No recipe gives skill past %d.|r"):format(reached)
        end
    end
    if reached < target and unpriced > 0 then
        notes[#notes + 1] = ("|cffaaaaaa%d recipe(s) left out: a material has no price yet. A full Auction House scan may fill them in.|r"):format(unpriced)
    end
    if toLearn > 0 then
        notes[#notes + 1] = ("|cffff8800%d step(s) use recipes you don't know yet|r (marked NOT LEARNED): get them first."):format(toLearn)
    end
    if not known or not live then
        notes[#notes + 1] = ("|cffff8800Open your %s window once|r so the plan starts at your skill and uses the recipes you know."):format(entry.name)
    end
    plan.notes = table.concat(notes, "\n")
    return plan
end
